mapper.select:
select t.fee_type_cd feeTypeCd,t.cur_year_month curYearMonth,t.detail_id detailId,t.remark,t.status_cd
statusCd,t.owner_id ownerId,t.ft_name ftName,t.fee_id feeId,t.pre_amount preAmount,t.payer_obj_name
payerObjName,t.owner_name ownerName,t.remain_amount remainAmount,t.his_owe_amount hisOweAmount,t.ft_id
ftId,t.community_id communityId,t.cur_amount curAmount,t.cur_owe_amount curOweAmount,t.ppf_id
ppfId,t.payer_obj_id payerObjId,t.create_time createTime,ppf.fee_name feeName
from pre_pay_fee_detail t
left join pre_pay_fee ppf on t.ppf_id = ppf.ppf_id
where 1 =1

    and t.fee_type_cd= #{feeTypeCd}


    and t.cur_year_month= #{curYearMonth}


    and t.detail_id= #{detailId}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.owner_id= #{ownerId}


    and t.ft_name= #{ftName}


    and t.fee_id= #{feeId}


    and t.pre_amount= #{preAmount}


    and t.payer_obj_name= #{payerObjName}


    and t.owner_name= #{ownerName}


    and t.remain_amount= #{remainAmount}


    and t.his_owe_amount= #{hisOweAmount}


    and t.ft_id= #{ftId}


    and t.community_id= #{communityId}


    and t.cur_amount= #{curAmount}


    and t.cur_owe_amount= #{curOweAmount}


    and t.ppf_id= #{ppfId}


    and t.payer_obj_id= #{payerObjId}

order by t.create_time desc

    limit #{page}, #{row}

